#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    int fish;

    Cat(string n, int f) : name(n), fish(f) {}
    void rename(string name) {
        name = name;
    }
    void show() const {
        cout << name << " 有 " << fish << " 条" << endl;
    }
};

int main() {
    Cat c1("小橘", 3);
    c1.rename("大胖");
    c1.show();
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    int fish;

    Cat(string n, int f) : name(n), fish(f) {}
    void rename(string name) {
        this->name = name;
    }
    void show() const {
        cout << name << " 有 " << fish << " 条" << endl;
    }
};

int main() {
    Cat c1("小橘", 3);
    Cat c2("狸花", 1);
    c1.rename("大胖");
    c1.show();
    c2.show();
    return 0;
}
